KILO_STATIC_ASSERT(offsetof(kilo_set_eyes_t, r) == 1, kilo_sa_set_eyes_r);
KILO_STATIC_ASSERT(offsetof(kilo_set_eyes_t, g) == 2, kilo_sa_set_eyes_g);
KILO_STATIC_ASSERT(offsetof(kilo_set_eyes_t, b) == 3, kilo_sa_set_eyes_b);

