KILO_STATIC_ASSERT(offsetof(kilo_telemetry_t, batt_mv) == 14, kilo_sa_telemetry_batt_mv);
KILO_STATIC_ASSERT(offsetof(kilo_telemetry_t, mode) == 16, kilo_sa_telemetry_mode);
KILO_STATIC_ASSERT(offsetof(kilo_telemetry_t, owners) == 17, kilo_sa_telemetry_owners);
